async function insertBlankPage(){if(!state.pages.length)return;const idx=selectedIndices();const ref=state.pages[idx.length?Math.max(...idx):state.pages.length-1];const size=pageSize(ref);let width=size?.width||595.28,height=size?.height||841.89;if(ref.rotation%180)[width,height]=[height,width];try{const source=await blankSource(width,height);recordHistory();const page={id:state.nextId++,sourceId:source.id,pageIndex:0,rotation:0};const now=selectedIndices();state.pages=insertPages(state.pages,[page],now.length?Math.max(...now)+1:state.pages.length);state.selected=new Set([page.id]);state.activePageId=page.id;state.anchor=page.id;renderPageList();renderViewer();status('Leere Seite eingefügt. Noch nicht exportiert.')}catch(error){console.error('Leere Seite konnte nicht erstellt werden',error);toast('Leere Seite konnte nicht erstellt werden.')}}
function suggestedFileName(indices,ext='pdf'){const sources=activeSources();const base=sources.length===1?sources[0].name.replace(/\.pdf$/i,''):sources.length?'zusammengefuehrt':'dokument';const suffix=!indices||isWholeDocument(indices)?'bearbeitet':indices.length===1?`seite-${indices[0]+1}`:'auswahl';return `${base}-${suffix}.${ext}`}
