// Word export (js/docx.js): text items + font names + image placements per page from PDF.js, laid out as paragraphs. Pages without text (scans) become one picture.
// Drawings, inserted elements, comments and form entries of the app are not part of it – it converts the PDF content.
const mul=(m,n)=>[m[0]*n[0]+m[2]*n[1],m[1]*n[0]+m[3]*n[1],m[0]*n[2]+m[2]*n[3],m[1]*n[2]+m[3]*n[3],m[0]*n[4]+m[2]*n[5]+m[4],m[1]*n[4]+m[3]*n[5]+m[5]];
