function imageSource(obj){if(!obj)return null;if(obj.bitmap)return obj.bitmap;if(!obj.data||!obj.width||!obj.height)return null;const {width:w,height:h,data,kind}=obj;const rgba=new Uint8ClampedArray(w*h*4);if(kind===3)rgba.set(data.subarray(0,rgba.length));else if(kind===2)for(let i=0,j=0;j<rgba.length;i+=3,j+=4){rgba[j]=data[i];rgba[j+1]=data[i+1];rgba[j+2]=data[i+2];rgba[j+3]=255}else if(kind===1){const row=(w+7)>>3;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const v=data[y*row+(x>>3)]&(128>>(x&7))?255:0,j=(y*w+x)*4;rgba[j]=rgba[j+1]=rgba[j+2]=v;rgba[j+3]=255}}else return null;const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').putImageData(new ImageData(rgba,w,h),0,0);return c}
