async function placedImage(source,w,h,ctm,map){const pt=(u,v)=>map.toView(ctm[0]*u+ctm[2]*v+ctm[4],ctm[1]*u+ctm[3]*v+ctm[5]);const v0=pt(0,1),v1=pt(1,1),v2=pt(0,0),v3=pt(1,0);const xs=[v0[0],v1[0],v2[0],v3[0]],ys=[v0[1],v1[1],v2[1],v3[1]];const minX=Math.min(...xs),minY=Math.min(...ys),bw=Math.max(...xs)-minX,bh=Math.max(...ys)-minY;if(bw<12||bh<12)return null;const density=Math.max(w/Math.hypot(v1[0]-v0[0],v1[1]-v0[1]),h/Math.hypot(v2[0]-v0[0],v2[1]-v0[1]));const s=Math.max(1,Math.min(density,4,2000/Math.max(bw,bh)));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bw*s));c.height=Math.max(1,Math.round(bh*s));const ctx=c.getContext('2d');const big=c.width*c.height>600000;if(big){ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height)}ctx.setTransform(s*(v1[0]-v0[0])/w,s*(v1[1]-v0[1])/w,s*(v2[0]-v0[0])/h,s*(v2[1]-v0[1])/h,s*(v0[0]-minX),s*(v0[1]-minY));ctx.drawImage(source,0,0);const type=big?'jpeg':'png';return {data:await canvasBytes(c,`image/${type}`,0.88),type,x0:minX,y0:minY,x1:minX+bw,y1:minY+bh}}
async function docxPage(p,images,cache){const source=state.sources.get(p.sourceId);const page=await source.pdf.getPage(p.pageIndex+1);const box=source.pageSizes[p.pageIndex];const text=await loadPageText(p);const fonts=new Map(),placed=[];const rotation=uprightRotation(text.items,p.rotation);const map=pageTransform(box,rotation,1);try{const ops=await page.getOperatorList();for(const item of text.items)if(item.fontName&&!fonts.has(item.fontName)&&page.commonObjs.has(item.fontName))fonts.set(item.fontName,page.commonObjs.get(item.fontName));for(const op of imageOps(ops)){const obj=op.obj||await pdfObject(page,op.id);const src=imageSource(obj);if(!src)continue;const key=`${p.sourceId}:${p.pageIndex}:${op.id||placed.length}:${op.ctm.map(n=>n.toFixed(2))}:${rotation}`;let img=cache.get(key);if(img===undefined){img=await placedImage(src,obj.width,obj.height,op.ctm,map).catch(()=>null);cache.set(key,img)}if(!img)continue;images.set(key,img);const [x0,y0]=map.toPdf(img.x0,img.y0),[x1,y1]=map.toPdf(img.x1,img.y1);placed.push({ref:key,x0,y0,x1,y1})}}catch(error){console.warn('Schriften/Bilder der Seite nicht lesbar',error)}const layout=layoutPage({items:text.items,fonts,box,rotation,images:placed});if(layout.text)return layout;const viewport=page.getViewport({scale:Math.min(150/72,2400/Math.max(box.width,box.height)),rotation:p.rotation});const canvas=document.createElement('canvas');canvas.width=Math.floor(viewport.width);canvas.height=Math.floor(viewport.height);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);prepareAnnotations(source,p);await page.render({canvasContext:ctx,viewport,...renderOptions}).promise;const ref=`scan:${p.id}`;images.set(ref,{data:await canvasBytes(canvas,'image/jpeg',0.85),type:'jpeg'});const m=18;return {width:layout.width,height:layout.height,margins:{top:m,right:m,bottom:m,left:m},blocks:[{type:'image',ref,width:layout.width-2*m,height:layout.height-2*m,align:'center'}],text:false}}
// „Wie im PDF“: the page is rendered twice at 150 dpi – once complete, once without text (fillText/strokeText do nothing; PDF.js draws loaded fonts with them).
// The second picture becomes the Word page background; where both differ under a text item, the complete one shows the text colour.
const docxModeKey='master-pdf-skill.docx-mode';
function docxModePref(){try{return localStorage.getItem(docxModeKey)==='flow'?'flow':'fixed'}catch{return 'fixed'}}
async function renderPagePicture(page,viewport,source,p,withText){const canvas=document.createElement('canvas');canvas.width=Math.floor(viewport.width);canvas.height=Math.floor(viewport.height);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);if(!withText){ctx.fillText=()=>{};ctx.strokeText=()=>{}}prepareAnnotations(source,p);await page.render({canvasContext:ctx,viewport,...renderOptions}).promise;return canvas}
// Colour of the text under one item and its ink (share of text pixels in the box, for guessBold).
function textInk(full,bare,w,h,corners){const xs=corners.map(c=>c[0]),ys=corners.map(c=>c[1]);const x0=Math.max(0,Math.floor(Math.min(...xs))),x1=Math.min(w,Math.ceil(Math.max(...xs))),y0=Math.max(0,Math.floor(Math.min(...ys))),y1=Math.min(h,Math.ceil(Math.max(...ys)));let max=0;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const i=(y*w+x)*4,d=Math.abs(full[i]-bare[i])+Math.abs(full[i+1]-bare[i+1])+Math.abs(full[i+2]-bare[i+2]);if(d>max)max=d}if(max<60)return {color:'',ink:0};let r=0,g=0,b=0,n=0,dark=0;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const i=(y*w+x)*4,d=Math.abs(full[i]-bare[i])+Math.abs(full[i+1]-bare[i+1])+Math.abs(full[i+2]-bare[i+2]);if(d>=max*0.7){r+=full[i];g+=full[i+1];b+=full[i+2];n++}if(d>=max*0.5)dark++}const hex=[r,g,b].map(v=>Math.round(v/n).toString(16).padStart(2,'0')).join('');return {color:/^[0-3][0-9a-f][0-3][0-9a-f][0-3][0-9a-f]$/.test(hex)?'':hex,ink:dark/Math.max(1,(x1-x0)*(y1-y0))}}
async function docxFixedPage(p,images){const source=state.sources.get(p.sourceId);const page=await source.pdf.getPage(p.pageIndex+1);const box=source.pageSizes[p.pageIndex];const text=await loadPageText(p);const rotation=uprightRotation(text.items,p.rotation);const scale=Math.min(150/72,2200/Math.max(box.width,box.height));const viewport=page.getViewport({scale,rotation});const full=await renderPagePicture(page,viewport,source,p,true);const bare=await renderPagePicture(page,viewport,source,p,false);const fonts=new Map();for(const item of text.items)if(item.fontName&&!fonts.has(item.fontName)&&page.commonObjs.has(item.fontName))fonts.set(item.fontName,page.commonObjs.get(item.fontName));const w=full.width,h=full.height,a=full.getContext('2d').getImageData(0,0,w,h).data,b=bare.getContext('2d').getImageData(0,0,w,h).data;const map=pageTransform(box,rotation,scale);const items=text.items.map(item=>{if(!item.str?.trim())return item;const t=item.transform,size=Math.hypot(t[2],t[3])||item.height||10,dl=Math.hypot(t[0],t[1])||1,du=Math.hypot(t[2],t[3])||1;const at=(u,v)=>map.toView(t[4]+t[0]/dl*item.width*u+t[2]/du*size*v,t[5]+t[1]/dl*item.width*u+t[3]/du*size*v);return {...item,...textInk(a,b,w,h,[at(0,-0.2),at(1,-0.2),at(0,0.8),at(1,0.8)])}});const ref=`seite:${p.id}`;images.set(ref,{data:await canvasBytes(bare,'image/jpeg',0.85),type:'jpeg'});return layoutFixed({items,fonts,box,rotation,background:ref})}
async function exportDocx(useSelection=false){if(state.exporting||!state.pages.length)return;closeTabMenu();const picker=typeof window.showSaveFilePicker==='function';const choice=await askExport(useSelection||state.selected.size>1?'pages':'all',!picker,'docx');if(!choice){status('Export abgebrochen.');return}const fixed=choice.docxMode!=='flow';try{localStorage.setItem(docxModeKey,fixed?'fixed':'flow')}catch{}const pages=choice.indices.map(i=>state.pages[i]);let handle=null,fileName=choice.name;if(picker){handle=await pickSaveHandle(suggestedFileName(choice.indices,'docx'),'docx');if(!handle){status('Export abgebrochen.');return}if(handle.fallbackName){fileName=handle.fallbackName;handle=null}}state.exporting=true;updateControls();showProgress(0);status('Word-Datei wird lokal erstellt …');try{const images=new Map(),cache=new Map(),layouts=[];let scans=0;for(let i=0;i<pages.length;i++){showProgress(i/pages.length);status(`Word-Datei wird lokal erstellt … Seite ${i+1} von ${pages.length}`);await nextTick();const layout=fixed?await docxFixedPage(pages[i],images):await docxPage(pages[i],images,cache);if(!layout.text&&!fixed)scans++;layouts.push(layout)}showProgress(null);status('Word-Datei wird geschrieben …');await nextTick();const title=(fileName||handle?.name||suggestedFileName(choice.indices,'docx')).replace(/\.docx$/i,'');const bytes=buildDocx(layouts,images,{title});const type=fileTypes.docx.accept;if(handle){const writable=await handle.createWritable();try{await writable.write(bytes);await writable.close()}catch(error){await writable.abort().catch(()=>{});throw error}fileName=handle.name;toast(`„${fileName}“ gespeichert.`)}else{const blob=new Blob([bytes],{type:Object.keys(type)[0]});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=fileName;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast(`„${fileName}“ erstellt, Download gestartet.`)}status(`Word-Export abgeschlossen: ${pagesLabel(pages.length)} → ${fileName}`+(scans?` (${scans===pages.length?'alle Seiten':scans===1?'1 Seite':`${scans} Seiten`} ohne Text, als Bild übernommen)`:''))}catch(error){console.error('Word-Export fehlgeschlagen',error);status('Word-Export fehlgeschlagen – es wurde keine Datei gespeichert.');toast('Word-Export fehlgeschlagen. Die Originaldateien blieben unverändert.')}finally{state.exporting=false;showProgress(false);updateControls()}}
