$('pdf-input').addEventListener('change',e=>{const files=[...e.target.files];e.target.value='';if(files.length&&confirmDiscard())openFiles(files,{replace:true})});$('pdf-add-input').addEventListener('change',e=>{const files=[...e.target.files];e.target.value='';if(files.length)openFiles(files,{insertAt:insertionIndex()})});['open-pdf','file-open'].forEach(id=>$(id).addEventListener('click',()=>$('pdf-input').click()));$('file-add').addEventListener('click',()=>$('pdf-add-input').click());$('file-new').addEventListener('click',newDocument);['export-pdf','file-export'].forEach(id=>$(id).addEventListener('click',()=>exportPdf()));['export-docx','file-export-docx'].forEach(id=>$(id).addEventListener('click',()=>exportDocx()));$('mode-read').addEventListener('click',()=>setMode('read'));$('mode-edit').addEventListener('click',()=>setMode('edit'));$('rotate-left').addEventListener('click',()=>rotateSelected(-90));$('rotate-right').addEventListener('click',()=>rotateSelected(90));['zoom-in','focus-zoom-in'].forEach(id=>$(id).addEventListener('click',()=>zoomBy(1)));['zoom-out','focus-zoom-out'].forEach(id=>$(id).addEventListener('click',()=>zoomBy(-1)));$('zoom-label').addEventListener('click',()=>setFit('auto'));$('fit-width').addEventListener('click',()=>setFit(state.fit==='width'?'auto':'width'));$('fit-page').addEventListener('click',()=>setFit(state.fit==='page'?'auto':'page'));$('view-spread').addEventListener('click',toggleSpread);$('view-focus').addEventListener('click',()=>setFocus(!state.focus));$('focus-exit').addEventListener('click',()=>setFocus(false));$('toggle-sidebar').addEventListener('click',toggleSidebar);$('export-cancel').addEventListener('click',()=>$('export-dialog').close('cancel'));
