// Not in the middle of a drawing or comment gesture (e.g. the scroll bar appearing when a tool bar shows all pages): it would replace the page under the pen.
let viewerResizeTimer=null;const resizeViewer=()=>{clearTimeout(viewerResizeTimer);viewerResizeTimer=setTimeout(()=>{if(drawGesture||commentGesture||textEdit||fillingField())resizeViewer();else if(state.pages.length)renderViewer()},120)};new ResizeObserver(resizeViewer).observe($('viewer'));
const narrowScreen=()=>matchMedia('(max-width:600px)').matches;
const sidebarKey=()=>'master-pdf-skill.sidebar-width'+(narrowScreen()?'-mobile':'');
function setSidebarWidth(px){const shell=document.querySelector('.app-shell');const narrow=narrowScreen();const max=narrow?shell.clientWidth-56:Math.max(220,shell.clientWidth-440);const width=Math.round(Math.max(narrow?120:200,Math.min(px,max)));shell.style.setProperty('--sidebar-width',`${width}px`);return width}
function saveSidebarWidth(){try{localStorage.setItem(sidebarKey(),String(Math.round($('sidebar').getBoundingClientRect().width)))}catch{}}
try{const saved=Number(localStorage.getItem(sidebarKey()));if(saved>0)setSidebarWidth(saved)}catch{}
const resizer=$('sidebar-resizer');
resizer.addEventListener('pointerdown',e=>{if(isCollapsed()||e.button!==0)return;e.preventDefault();const sidebar=$('sidebar');const startX=e.clientX,startWidth=sidebar.getBoundingClientRect().width;resizer.setPointerCapture(e.pointerId);sidebar.classList.add('resizing');document.body.classList.add('resizing-sidebar');const move=ev=>setSidebarWidth(startWidth+ev.clientX-startX);const up=()=>{resizer.removeEventListener('pointermove',move);resizer.removeEventListener('pointerup',up);resizer.removeEventListener('pointercancel',up);sidebar.classList.remove('resizing');document.body.classList.remove('resizing-sidebar');document.getSelection()?.removeAllRanges();saveSidebarWidth()};resizer.addEventListener('pointermove',move);resizer.addEventListener('pointerup',up);resizer.addEventListener('pointercancel',up)});
resizer.addEventListener('mousedown',e=>e.preventDefault());
