resizer.addEventListener('keydown',e=>{if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;e.preventDefault();setSidebarWidth($('sidebar').getBoundingClientRect().width+(e.key==='ArrowRight'?40:-40));saveSidebarWidth()});
const pageList=$('page-list');
