const dropClasses=['drop-before','drop-after','drop-above','drop-below'];
function clearDropIndicator(){pageList.classList.remove('files-over','pages-over');pageList.querySelectorAll('.'+dropClasses.join(',.')).forEach(el=>el.classList.remove(...dropClasses));state.dropTarget=null}
function showDropIndicator(target,files){const cls=target.vertical?(target.after?'drop-below':'drop-above'):(target.after?'drop-after':'drop-before');pageList.querySelectorAll('.'+dropClasses.join(',.')).forEach(el=>{if(el!==target.card)el.classList.remove(...dropClasses)});if(target.card){dropClasses.forEach(c=>target.card.classList.toggle(c,c===cls));const text=files?'PDF hier':'hier';target.card.dataset.dropLabel={'drop-before':`◀ ${text}`,'drop-after':`${text} ▶`,'drop-above':`▲ ${text}`,'drop-below':`▼ ${text}`}[cls]}pageList.classList.toggle('files-over',files);pageList.classList.toggle('pages-over',!files)}
