pageList.addEventListener('drop',e=>{if(e.dataTransfer?.files?.length||state.dragId==null)return;e.preventDefault();const target=state.dropTarget||dropTargetAt(e);const dragged=state.dragId;clearDropIndicator();movePagesTo(dragged,target)});
