document.addEventListener('drop',e=>{if(!e.dataTransfer?.files?.length)return;e.preventDefault();const insert=editing()&&state.pages.length>0;const insertAt=insert&&pageList.contains(e.target)?insertIndexFor(state.dropTarget):null;clearDropIndicator();if(insert)openFiles(e.dataTransfer.files,{insertAt});else if(confirmDiscard())openFiles(e.dataTransfer.files,{replace:true})});
