const toolNames={'i-field-text':'Formular-Textfeld: auf der Seite aufziehen (ab etwa zwei Zeilen Höhe mehrzeilig) oder antippen.','i-field-check':'Kontrollkästchen: auf der Seite antippen oder aufziehen.','i-text':'Text: auf die Seite tippen und schreiben, vorhandenen Text antippen zum Ändern.',select:'Auswählen: Element antippen, ziehen zum Verschieben, an den Anfassern die Größe ändern, Entf löscht.',pen:'Stift: auf der Seite zeichnen.',marker:'Textmarker: frei über die Seite streichen.',eraser:'Radierer: ganze Elemente antippen oder überstreichen.',line:'Linie: ziehen, mit Shift in 45°-Schritten.',arrow:'Pfeil: vom Anfang zur Spitze ziehen, mit Shift in 45°-Schritten.',rect:'Rechteck: ziehen, mit Shift quadratisch.',ellipse:'Ellipse: ziehen, mit Shift als Kreis.'};
