// Next to the bar on the side with more room (right of a bar docked left, under a bar docked top), level with the button.
function placeToolPop(){const btn=state.popAnchor;if(!btn)return;const pop=$('tool-pop'),box=btn.closest('.toolbox'),b=box.getBoundingClientRect(),a=btn.getBoundingClientRect(),w=pop.offsetWidth,h=pop.offsetHeight;let x,y;if(box.dataset.dock==='top'){x=a.left+a.width/2-w/2;y=b.bottom+8}else{x=b.left+b.width/2>innerWidth/2?b.left-w-8:b.right+8;y=a.top+a.height/2-h/2}pop.style.left=`${Math.max(8,Math.min(x,innerWidth-w-8))}px`;pop.style.top=`${Math.max(8,Math.min(y,innerHeight-h-8))}px`}
$('tool-pop').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();const btn=state.popAnchor;closeToolPop();btn?.focus()}});
document.addEventListener('pointerdown',e=>{const t=e.target instanceof Element?e.target:null;if(!t?.closest('.tab-menu,.menu-tab'))closeTabMenu();if(state.popAnchor&&!t?.closest('#tool-pop,.has-options'))closeToolPop()},true);
window.addEventListener('resize',()=>{closeTabMenu();closeToolPop()});
// Topbar tabs show icon + label; when the row does not fit (phone), .tabs-compact hides the labels and leaves the icons. Re-checked when the topbar changes size and on mode switch.
function fitTabs(){const bar=document.querySelector('.topbar');bar.classList.remove('tabs-compact');if(bar.scrollWidth>bar.clientWidth+1)bar.classList.add('tabs-compact')}new ResizeObserver(fitTabs).observe(document.querySelector('.topbar'));
// Group buttons show the icon of the kind they would pick, the colour buttons the colour of the tool or the selected element.
function renderToolbox(){if(!state.toolboxReady)return;const has=state.pages.length>0;for(const [group,id] of [['shape','tool-shapes'],['markup','tool-c-markup'],['field','tool-i-fields']]){const btn=$(id),kind=state.toolGroups[group];btn.setAttribute('aria-pressed',String(groupOf(state.tool)===group));if(btn.dataset.icon!==kind){const icon=document.querySelector(`#tool-pop [data-tool="${kind}"] svg`);if(icon){btn.dataset.icon=kind;btn.replaceChildren(icon.cloneNode(true))}}}const draw=styleContext();$('draw-color').disabled=!has||!!draw.eraser||!!draw.image;if(!draw.eraser&&!draw.image)$('draw-color').style.setProperty('--dot',draw.color);$('comment-color').disabled=!has;$('comment-color').style.setProperty('--dot',commentColorContext().color);if(state.popAnchor?.disabled)closeToolPop()}
state.toolboxReady=true;renderToolbox();
// Form fields (forms.js): source.fields[pageIndex] are read on open (owner = source id), fields created in the „Einfügen“ bar are field marks shown through createdField() (owner NEW_FIELDS, same name on every copy of a page = one field). state.forms holds only the changed values (fieldKey(owner, name) → value), so undo/redo, thumbnails (thumbKey) and the export see them. PDF.js draws read checkbox/radio/choice values into the canvas from its annotation storage (prepareFields, ENABLE_STORAGE); the .form-layer on top takes the input – its text stays transparent unless the field is being edited, the canvas is still being redrawn (.pending) or the app draws the field itself (.own: changed read text fields and all created fields).
function pageFields(p){const read=state.sources.get(p.sourceId)?.fields?.[p.pageIndex]||[],made=(p.marks||[]).filter(m=>m.type==='field').map(createdField);return made.length?[...read,...made]:read}
const keyOf=f=>fieldKey(f.owner,f.name);
function formValue(f){const key=keyOf(f);return state.forms.has(key)?state.forms.get(key):f.value}
const ownDrawn=f=>f.created||(f.kind==='text'&&state.forms.has(keyOf(f)));
const hashText=text=>{let h=0;for(let i=0;i<text.length;i++)h=Math.imul(h,31)+text.charCodeAt(i)|0;return (h>>>0).toString(36)};
function filledKey(p){const parts=[];for(const f of pageFields(p)){const key=keyOf(f);if(state.forms.has(key))parts.push(`${f.name}=${JSON.stringify(state.forms.get(key))}`)}return parts.length?hashText(parts.join('|')):''}
// Changed text fields are hidden in the canvas and drawn by the app (form layer, fieldTextLayer in thumbnails): PDF.js draws auto-sized multi-line fields with only the first line in a huge font.
function prepareFields(source,p){const storage=source.pdf.annotationStorage;for(const f of pageFields(p)){if(f.created)continue;const key=keyOf(f);if(!state.forms.has(key)){if(storage.getRawValue(f.id)!==undefined)storage.remove(f.id)}else if(f.kind==='text')storage.setValue(f.id,{noView:true});else storage.setValue(f.id,{value:storageValue(f,state.forms.get(key))})}}
function fieldFrame(p,f,map){const [x0,y0,x1,y1]=f.rect,a=map.toView(x0,y0),b=map.toView(x1,y1),turn=(((p.rotation-f.rotation)%360)+360)%360,fw=f.rotation%180?y1-y0:x1-x0,fh=f.rotation%180?x1-x0:y1-y0;return {cx:(a[0]+b[0])/2,cy:(a[1]+b[1])/2,w:fw*map.scale,h:fh*map.scale,turn}}
function fieldTextLayer(p,map){const items=pageFields(p).filter(f=>ownDrawn(f)&&state.forms.has(keyOf(f)));if(!items.length)return null;const svg=svgLayer('field-text',map);for(const f of items){const {cx,cy,w,h,turn}=fieldFrame(p,f,map),value=state.forms.get(keyOf(f)),g=svgEl('g',{transform:`translate(${cx} ${cy}) rotate(${turn})`}),box=svgEl('svg',{x:-w/2,y:-h/2,width:w,height:h});if(f.kind==='checkbox'){if(value===f.on){const t=svgEl('text',{x:w/2,y:h*.8,'font-size':h*.9,'text-anchor':'middle'});t.textContent='✓';box.append(t)}}else{const size=fieldFontSize(f)*map.scale,pad=2*map.scale;measureCtx.font=`${size}px Helvetica, Arial, sans-serif`;const text=String(value);const lines=f.multiline?text.split('\n').flatMap(line=>wrapText(line,w-2*pad,t=>measureCtx.measureText(t).width)):[text.replace(/\n/g,' ')];lines.forEach((line,i)=>{const t=svgEl('text',{x:f.align==='center'?w/2:f.align==='right'?w-pad:pad,y:f.multiline?pad+size*(i+.9):h/2+size*.35,'font-size':size,'text-anchor':{left:'start',center:'middle',right:'end'}[f.align]});t.textContent=line;box.append(t)})}g.append(box);svg.append(g)}return svg}
function changedFormValues(owner){const values=new Map();for(const [key,value] of state.forms){const cut=key.indexOf('\u0000');if(key.slice(0,cut)===owner)values.set(key.slice(cut+1),value)}return values.size?values:null}
function usedFieldNames(){const names=new Set();for(const source of state.sources.values())for(const list of source.fields||[])for(const f of list)names.add(f.name);for(const p of state.pages)for(const m of p.marks||[])if(m.type==='field')names.add(m.name);for(const key of state.forms.keys())if(key.startsWith(`${NEW_FIELDS}\u0000`))names.add(key.slice(NEW_FIELDS.length+1));return names}
const fillingField=()=>!!document.activeElement?.classList?.contains('form-field');
function formLayer(p,map){const fields=pageFields(p).filter(f=>!f.readOnly);if(!fields.length)return null;const layer=document.createElement('div');layer.className='form-layer';for(const f of fields)layer.append(formControl(p,f,map));return layer}
// Rebuilt after field marks changed (refreshMarks); a field being typed in is left alone.
function syncFormLayer(wrap,record){if(fillingField()&&wrap.contains(document.activeElement))return;wrap.querySelector(':scope > .form-layer')?.remove();const layer=formLayer(record,wrap._map);if(layer)wrap.append(layer)}
function formControl(p,f,map){const value=formValue(f),{cx,cy,w,h,turn}=fieldFrame(p,f,map);let el;
if(f.kind==='text'){el=document.createElement(f.multiline?'textarea':'input');if(!f.multiline)el.type='text';el.value=value;if(f.maxLen)el.maxLength=f.maxLen;el.spellcheck=false;el.autocomplete='off';el.style.textAlign=f.align;el.style.fontSize=`${fieldFontSize(f)*map.scale}px`;el.addEventListener('blur',()=>commitField(f,el.value));el.addEventListener('keydown',e=>{if(e.key==='Escape'){el.value=formValue(f);el.blur()}else if(e.key==='Enter'&&!f.multiline){e.preventDefault();el.blur()}})}
else if(f.kind==='choice'){el=document.createElement('select');el.multiple=f.multiple;if(!f.combo)el.size=2;if(f.combo&&!f.multiple)el.append(new Option('',''));for(const o of f.options)el.append(new Option(o.label,o.value,false,value.includes(o.value)));if(f.combo&&!value.length)el.selectedIndex=0;el.style.fontSize=`${fieldFontSize(f)*map.scale}px`;el.addEventListener('change',()=>commitField(f,[...el.selectedOptions].map(o=>o.value).filter(v=>v!=='')))}
else{el=document.createElement('button');el.type='button';el.setAttribute('role',f.kind);el.setAttribute('aria-checked',String(value===f.on));el.style.fontSize=`${h*.9}px`;el.addEventListener('click',()=>commitField(f,tappedValue(f,formValue(f))))}
el._field=f;el.classList.add('form-field',`form-${f.kind}`);el.classList.toggle('own',ownDrawn(f));el.dataset.field=f.name;el.dataset.source=f.owner;el.title=f.tip||f.name;el.setAttribute('aria-label',f.tip||f.name);Object.assign(el.style,{left:`${cx-w/2}px`,top:`${cy-h/2}px`,width:`${w}px`,height:`${h}px`,transform:turn?`rotate(${turn}deg)`:''});el.addEventListener('focus',()=>el.classList.add('editing'));el.addEventListener('blur',()=>el.classList.remove('editing'));el.addEventListener('pointerdown',e=>e.stopPropagation());return el}
// One history entry per change (a text field commits when it loses focus); all widgets of the field show the new value.
function commitField(f,value){if(sameValue(value,formValue(f)))return;const key=keyOf(f);recordHistory();if(sameValue(value,f.value))state.forms.delete(key);else state.forms.set(key,value);refreshField(f.owner,f.name);renderPageList();status('Formular ausgefüllt – noch nicht exportiert.')}
function refreshField(owner,name){const viewer=$('viewer');const done=wrap=>wrap.querySelectorAll('.form-field.pending').forEach(el=>el.classList.remove('pending'));for(const el of viewer.querySelectorAll('.form-field')){if(el.dataset.source!==owner||el.dataset.field!==name)continue;const f=el._field,value=formValue(f),own=ownDrawn(f);el.classList.toggle('own',own);if(f.kind==='text'){if(el!==document.activeElement)el.value=value;if(!own)el.classList.add('pending')}else if(f.kind==='choice'){for(const o of el.options)o.selected=o.value?value.includes(o.value):!value.length;el.classList.add('pending')}else el.setAttribute('aria-checked',String(value===f.on))}if(owner===NEW_FIELDS)return;for(const wrap of viewer.querySelectorAll('.reader-page')){const record=state.pages.find(p=>p.id===Number(wrap.dataset.id));if(!record||record.sourceId!==owner||!pageFields(record).some(f=>f.name===name))continue;wrap.dataset.key=thumbKey(record);if(!wrap.dataset.drawn){done(wrap);continue}delete wrap.dataset.drawn;drawReaderPage(wrap).finally(()=>done(wrap))}}
// ?demo=1 (Vorschau auf der MPSkills-Startseite): ein Beispieldokument mit Zeichnungen und Kommentaren, nichts wird gespeichert.
async function startDemo(){const bytes=await createDemoPdf();await openFiles([new File([bytes],'Zahlensysteme im Tierreich.pdf',{type:'application/pdf'})],{replace:true});const decor=demoDecor();state.pages=state.pages.map((p,i)=>({...p,...(decor[i]?.marks.length?{marks:decor[i].marks}:{}),...(decor[i]?.comments.length?{comments:decor[i].comments}:{})}));await renderViewer();renderPageList();updateControls()}
if(new URLSearchParams(location.search).has('demo'))startDemo().catch(e=>console.error('Demo konnte nicht gestartet werden',e));
document.documentElement.dataset.ready='1';
